class Shape:
    def __init__(self, name):
        self.name = name

    def area(self):
        return 0


class Square(Shape):
    def __init__(self, name, side):
        super().__init__(name)
        self.side = side

    def area(self):
        return self.side * self.side


side = int(input())
generic = Shape("shape")
box = Square("box", side)
print(generic.area())
print(box.area())

