class Employee:
    def __init__(self, name, base):
        self.name = name
        self.base = base

    def monthly_pay(self):
        return self.base

    def __lt__(self, other):
        return self.monthly_pay() < other.monthly_pay()


class Manager(Employee):
    def monthly_pay(self):
        return super().monthly_pay() + 5000


class Developer(Employee):
    def monthly_pay(self):
        return super().monthly_pay() + 2000


class Intern(Employee):
    def monthly_pay(self):
        return super().monthly_pay() // 2


n = int(input())
roles = {"Manager": Manager, "Developer": Developer, "Intern": Intern}
staff = []
for _ in range(n):
    name, role, base = input().split()
    staff.append(roles[role](name, int(base)))

for person in sorted(staff):
    print(person.name, person.__class__.__name__, person.monthly_pay())

class Shape:
    def __init__(self, name):
        self.name = name

    def area(self):
        return 0

    def __add__(self, other):
        return Bundle(self.name + "+" + other.name, self.area() + other.area())

    def __gt__(self, other):
        return self.area() > other.area()

    def __str__(self):
        return f"{self.name}: {self.area():.2f}"


class Bundle(Shape):
    def __init__(self, name, total):
        super().__init__(name)
        self.total = total

    def area(self):
        return self.total


class Square(Shape):
    def __init__(self, side):
        super().__init__("Square")
        self.side = side

    def area(self):
        return self.side * self.side


class Rect(Shape):
    def __init__(self, w, h):
        super().__init__("Rect")
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h


class Circle(Shape):
    def __init__(self, r):
        super().__init__("Circle")
        self.r = r

    def area(self):
        return 3.14 * self.r * self.r


n = int(input())
shapes = []
for _ in range(n):
    parts = input().split()
    kind = parts[0]
    if kind == "square":
        shapes.append(Square(int(parts[1])))
    elif kind == "rect":
        shapes.append(Rect(int(parts[1]), int(parts[2])))
    else:
        shapes.append(Circle(int(parts[1])))

combined = shapes[0]
for s in shapes[1:]:
    combined = combined + s
print(str(combined))

best = shapes[0]
for s in shapes[1:]:
    if s > best:
        best = s
print(str(best))

class CartItem:
    def __init__(self, name, price, qty):
        self.name = name
        self.price = price
        self.qty = qty

    def __eq__(self, other):
        return self.name == other.name and self.price == other.price


n = int(input())
merged = []
for _ in range(n):
    name, price, qty = input().split()
    item = CartItem(name, int(price), int(qty))
    combined = False
    for existing in merged:
        if item == existing:
            existing.qty += item.qty
            combined = True
            break
    if not combined:
        merged.append(item)

for m in merged:
    print(m.name, m.price, m.qty)
print(f"Distinct items: {len(merged)}")

class CsvExport:
    def export(self, name, marks):
        return f"{name},{marks}"


class JsonExport:
    def export(self, name, marks):
        return '{"name": "' + name + '", "marks": ' + str(marks) + '}'


class XmlExport:
    def export(self, name, marks):
        return f'<student name="{name}" marks="{marks}"/>'


fmt = input()
n = int(input())
records = []
for _ in range(n):
    parts = input().split()
    records.append((parts[0], int(parts[1])))

if fmt == "csv":
    exporter = CsvExport()
elif fmt == "json":
    exporter = JsonExport()
else:
    exporter = XmlExport()

if fmt == "xml":
    print("<students>")
if fmt == "json":
    print('{"students": [')
for i, (name, marks) in enumerate(records):
    line = exporter.export(name, marks)
    if fmt == "json":
        tail = "," if i < len(records) - 1 else ""
        line = "  " + line + tail
    print(line)
if fmt == "xml":
    print("</students>")
if fmt == "json":
    print("]}")
